/** Props shared by React and native, icon-only toolbar and floating buttons. */
const SVG_NAMESPACE = 'http://www.w3.org/2000/svg'
const SHARED_ICON_TAGS = new Set(['circle', 'ellipse', 'line', 'path', 'polygon', 'polyline', 'rect'])
const PANEL_CONTROL_GROUP_CLASS = 'agentic-panel-control-group'
const PANEL_CONTROL_GROUP_LABEL = 'Panel controls'
const panelControlActions = new WeakMap()
const panelControlButtons = new WeakMap()
const panelControlGroups = new WeakMap()

/** Render one icon from the central Design System registry. */
export function createDesignIcon(name, ownerDocument = globalThis.document) {
  const nodes = iconLibrary.icons[name]
  if (!Array.isArray(nodes)) throw new RangeError(`Unknown shared icon: ${name}`)
  if (!ownerDocument?.createElementNS) throw new TypeError('An owner document is required to create an icon')

  const icon = ownerDocument.createElementNS(SVG_NAMESPACE, 'svg')
  for (const [attribute, value] of Object.entries({
    viewBox: iconLibrary.viewBox,
    fill: 'none',
    stroke: 'currentColor',
    'stroke-linecap': 'round',
    'stroke-linejoin': 'round',
    class: 'agentic-icon',
    'aria-hidden': 'true',
    focusable: 'false',
  })) icon.setAttribute(attribute, value)

  for (const [tag, attributes] of nodes) {
    if (!SHARED_ICON_TAGS.has(tag)) throw new TypeError(`Unsupported shared icon node: ${tag}`)
    const node = ownerDocument.createElementNS(SVG_NAMESPACE, tag)
    for (const [attribute, value] of Object.entries(attributes)) node.setAttribute(attribute, String(value))
    icon.append(node)
  }
  return icon
}

/** Resolve a panel action through its centrally owned semantic icon role. */
export function createPanelControlIcon(control, ownerDocument = globalThis.document) {
  const definition = iconLibrary.panelControls?.[control]
  if (!definition || typeof definition.icon !== 'string') throw new RangeError(`Unknown shared panel control: ${control}`)
  return createDesignIcon(definition.icon, ownerDocument)
}

/** Return the canonical accessible name for a semantic panel control role. */
export function getPanelControlLabel(control) {
  const label = iconLibrary.panelControls?.[control]?.label
  if (typeof label !== 'string') throw new RangeError(`Unknown shared panel control: ${control}`)
  return label
}

/** Apply one canonical icon, accessible name and title to an existing panel button. */
export function applyPanelControl(button, control) {
  const definition = iconLibrary.panelControls?.[control]
  if (!definition || typeof definition.icon !== 'string' || typeof definition.label !== 'string') {
    throw new RangeError(`Unknown shared panel control: ${control}`)
  }
  if (!button || button.localName !== 'button' || !button.ownerDocument?.createElementNS) {
    throw new TypeError('A panel control must be a button in an owner document')
  }
  const existingControl = button.dataset.agenticPanelControl
  if (existingControl && existingControl !== control) {
    throw new TypeError(`Panel control cannot replace its existing semantic role: ${existingControl}`)
  }
  for (const attribute of ['aria-label', 'title']) {
    const existing = button.getAttribute(attribute)
    if (button.hasAttribute(attribute) && existing !== '' && existing !== definition.label) {
      throw new TypeError(`Panel control ${control} cannot override its canonical ${attribute}`)
    }
  }
  if (button.hasAttribute('aria-labelledby') || (control !== 'pin' && button.hasAttribute('aria-pressed'))) {
    throw new TypeError(`Panel control ${control} cannot override its canonical accessible state`)
  }
  const allowedClasses = new Set(control === 'close'
    ? ['agentic-toolbar-item', 'agentic-base-floating-panel-close']
    : ['agentic-toolbar-item'])
  if ([...button.classList].some(className => !allowedClasses.has(className)) || button.hasAttribute('style')) {
    throw new TypeError(`Panel control ${control} cannot apply consumer visual overrides`)
  }
  button.type = 'button'
  button.dataset.agenticPanelControl = control
  button.setAttribute('aria-label', definition.label)
  button.title = definition.label
  button.classList.add('agentic-toolbar-item')
  button.dataset.iconOnly = ''
  if (control === 'close') button.classList.add('agentic-base-floating-panel-close')
  button.replaceChildren(createPanelControlIcon(control, button.ownerDocument))
  return button
}

/** Render one icon-only button from the semantic panel-control registry. */
export function createPanelControlButton(control, ownerDocument = globalThis.document) {
  if (!ownerDocument?.createElement) throw new TypeError('An owner document is required to create a panel control')
  return applyPanelControl(ownerDocument.createElement('button'), control)
}

function runPanelControlAction(event) {
  event.preventDefault()
  event.stopPropagation()
  const button = event.currentTarget
  if (button.disabled) return
  panelControlActions.get(button)?.()
}

function bindPanelControlButton(button) {
  if (panelControlButtons.has(button)) return
  for (const name of ['pointerdown', 'pointerup']) button.addEventListener(name, event => event.stopPropagation())
  button.addEventListener('click', runPanelControlAction)
  panelControlButtons.set(button, true)
}

/** Update the canonical DOM button while binding only the app-owned callback and state. */
export function updatePanelControlButton(button, control, { action, disabled = false, pressed = false } = {}) {
  applyPanelControl(button, control)
  bindPanelControlButton(button)
  panelControlActions.set(button, typeof action === 'function' ? action : undefined)
  button.disabled = disabled === true || typeof action !== 'function'
  if (control === 'pin') button.setAttribute('aria-pressed', String(pressed === true))
  return button
}

/** Resolve control order and minimized visibility from the central semantic registry. */
export function resolvePanelControlRoles({ actions = {}, minimized = false } = {}) {
  const definitions = iconLibrary.panelControls
  if (!definitions || typeof definitions !== 'object' || Array.isArray(definitions)) {
    throw new TypeError('The Design System panel-control registry is unavailable')
  }
  if (!actions || typeof actions !== 'object' || Array.isArray(actions)) {
    throw new TypeError('Panel-control actions must be an object')
  }
  if (typeof minimized !== 'boolean') throw new TypeError('Panel minimized state must be boolean')
  const roles = Object.keys(definitions)
  for (const [control, action] of Object.entries(actions)) {
    if (!Object.hasOwn(definitions, control)) throw new RangeError(`Unknown shared panel control: ${control}`)
    if (action !== undefined && typeof action !== 'function') throw new TypeError(`Panel control ${control} action must be a function`)
  }
  return roles.filter(control => {
    if (typeof actions[control] !== 'function') return false
    if (control === 'minimize') return !minimized && typeof actions.minimize === 'function'
    if (control === 'restore') return minimized && typeof actions.restore === 'function'
    if (minimized && ['search', 'apply', 'reset'].includes(control)) return false
    return true
  })
}

/** Render and update one Design System-owned control group without consumer variants. */
export function updatePanelControlGroup(group, { actions = {}, disabled = {}, minimized = false, pinned = false } = {}) {
  if (!group || group.localName !== 'section') throw new TypeError('A panel-control group must be a section')
  if (group.getAttribute('role') !== 'group' || group.getAttribute('aria-label') !== PANEL_CONTROL_GROUP_LABEL
    || group.className !== PANEL_CONTROL_GROUP_CLASS || group.hasAttribute('style')) {
    throw new TypeError('A panel-control group cannot override its shared role, label, class, or visuals')
  }
  if (!disabled || typeof disabled !== 'object' || Array.isArray(disabled)) {
    throw new TypeError('Panel-control disabled state must be an object')
  }
  if (typeof pinned !== 'boolean') throw new TypeError('Panel pin state must be boolean')
  const definitions = iconLibrary.panelControls
  for (const [control, value] of Object.entries(disabled)) {
    if (!Object.hasOwn(definitions, control)) throw new RangeError(`Unknown shared panel control: ${control}`)
    if (value !== undefined && typeof value !== 'boolean') throw new TypeError(`Panel control ${control} disabled state must be boolean`)
  }
  const cache = panelControlGroups.get(group) ?? new Map()
  panelControlGroups.set(group, cache)
  const roles = resolvePanelControlRoles({ actions, minimized })
  const buttons = roles.map(control => {
    let button = cache.get(control)
    if (!button) {
      button = createPanelControlButton(control, group.ownerDocument)
      cache.set(control, button)
    }
    updatePanelControlButton(button, control, {
      action: actions[control], disabled: disabled[control] === true, pressed: control === 'pin' && pinned,
    })
    return button
  })
  const current = [...group.children]
  const currentRoles = current.map(child => child.dataset?.agenticPanelControl)
  if (current.some((child, index) => child.localName !== 'button'
    || !Object.hasOwn(definitions, currentRoles[index])
    || cache.get(currentRoles[index]) !== child)
    || new Set(currentRoles).size !== currentRoles.length) {
    throw new TypeError('A panel-control group cannot contain consumer controls')
  }
  if (current.length !== buttons.length || current.some((button, index) => button !== buttons[index])) {
    group.replaceChildren(...buttons)
  }
  return group
}

/** Hydrate role-marked buttons from the one panel-control registry. */
export function hydratePanelControls(root = globalThis.document) {
  if (!root?.querySelectorAll) throw new TypeError('A panel control hydration root is required')
  const buttons = [...root.querySelectorAll('[data-agentic-panel-control]')]
  for (const button of buttons) applyPanelControl(button, button.dataset.agenticPanelControl)
  return buttons.length
}

/** Hydrate declarative icon placeholders without copying SVG paths into consumers. */
export function hydrateDesignIcons(root = globalThis.document) {
  if (!root?.querySelectorAll) throw new TypeError('An icon hydration root is required')
  const placeholders = [...root.querySelectorAll('[data-agentic-design-icon]')]
  for (const placeholder of placeholders) {
    const icon = createDesignIcon(placeholder.getAttribute('data-agentic-design-icon'), placeholder.ownerDocument)
    const className = placeholder.getAttribute('class')
    if (className) icon.setAttribute('class', className)
    placeholder.replaceWith(icon)
  }
  return placeholders.length
}

export function getIconButtonProps(label) {
  return {
    type: 'button',
    className: 'agentic-toolbar-item',
    'data-icon-only': '',
    'aria-label': label,
  };
}

export function getIconSizeClass(scale = 'default') {
  return scale === 'compact' ? 'agentic-icon agentic-icon-compact' : 'agentic-icon';
}

export function createIconButton(label, glyph) {
  const button = glyph.ownerDocument.createElement('button');
  const { className, ...attributes } = getIconButtonProps(label);
  button.className = className;
  for (const [name, value] of Object.entries(attributes)) button.setAttribute(name, value);
  glyph.setAttribute('class', getIconSizeClass());
  glyph.setAttribute('role', 'img');
  glyph.setAttribute('aria-label', `${label} icon`);
  glyph.setAttribute('focusable', 'false');
  glyph.setAttribute('stroke', 'currentColor');
  glyph.setAttribute('fill', 'none');
  button.append(glyph);
  return button;
}


/** Mount the native shell around product-owned tab contents. Build its chrome on first open. */
export function mountFloatingPanel(trigger, root, {
  label, tablistLabel = label, activeKey, placement = 'viewport-overlay', returnFocus = () => trigger.focus(), onChange,
}) {
  const doc = root.ownerDocument;
  const pages = [...root.children];
  const keys = pages.map(page => page.dataset.panelTab);
  if (!root.id || !label || !tablistLabel || !pages.length || new Set(keys).size !== pages.length
      || pages.some(page => !/^[a-z][a-z0-9-]*$/.test(page.dataset.panelTab ?? '') || !page.dataset.panelLabel)
      || !['flow', 'dock', 'viewport-overlay'].includes(placement)) throw new TypeError('Invalid FloatingPanel binding');
  let selected = activeKey ?? keys[0];
  if (!keys.includes(selected)) throw new RangeError('Unknown initial FloatingPanel tab');
  const element = (tag, className) => {
    const node = doc.createElement(tag);
    node.className = className;
    return node;
  };
  const tabs = new Map();
  function select(key, focus = false) {
    if (!keys.includes(key)) throw new RangeError('Unknown FloatingPanel tab');
    const changed = selected !== key;
    selected = key;
    if (!tabs.size) return;
    for (const [index, page] of pages.entries()) {
      const active = keys[index] === key;
      const tab = tabs.get(keys[index]);
      tab.setAttribute('aria-selected', String(active));
      tab.tabIndex = active ? 0 : -1;
      page.hidden = !active;
    }
    const tab = tabs.get(key);
    if (focus) tab.focus({ preventScroll: true });
    const rail = tab.parentElement;
    const box = tab.getBoundingClientRect(), clip = rail.getBoundingClientRect();
    rail.scrollLeft += Math.min(0, box.left - clip.left) + Math.max(0, box.right - clip.right);
    if (changed && !root.hidden) onChange?.({ open: true, key });
  }
  function build() {
    const dialog = element('aside', 'agentic-base-floating-panel agentic-form-controls');
    dialog.setAttribute('role', 'dialog');
    dialog.setAttribute('aria-modal', 'false');
    dialog.setAttribute('aria-label', label);
    const inner = element('section', 'agentic-base-floating-panel-inner agentic-base-floating-panel-expanded');
    const header = element('header', 'agentic-panel-header agentic-base-floating-panel-header');
    const rail = element('nav', 'agentic-floating-panel-tabs');
    rail.setAttribute('role', 'tablist');
    rail.setAttribute('aria-label', tablistLabel);
    rail.setAttribute('aria-orientation', 'horizontal');
    const controls = element('section', 'agentic-panel-control-group');
    controls.setAttribute('role', 'group');
    controls.setAttribute('aria-label', 'Panel controls');
    updatePanelControlGroup(controls, { actions: { close } });
    for (const [i, page] of pages.entries()) {
      const key = keys[i], name = page.dataset.panelLabel;
      page.id ||= root.id + '-' + key;
      const tab = element('button', 'agentic-floating-panel-tab');
      tab.type = 'button';
      tab.id = page.id + '-tab';
      tab.dataset.agenticFloatingPanelTabKey = key;
      tab.title = name;
      tab.setAttribute('role', 'tab');
      tab.setAttribute('aria-label', name);
      tab.setAttribute('aria-controls', page.id);
      if (page.dataset.panelIcon) tab.append(createDesignIcon(page.dataset.panelIcon, doc));
      const caption = doc.createElement('span');
      caption.textContent = name;
      tab.append(caption);
      page.classList.add('agentic-floating-panel-body');
      page.setAttribute('role', 'tabpanel');
      page.setAttribute('aria-labelledby', tab.id);
      page.tabIndex = 0;
      tabs.set(key, tab);
      rail.append(tab);
      tab.addEventListener('click', () => select(key, true));
    }
    rail.addEventListener('keydown', event => {
      const index = keys.indexOf(event.target.closest('[role="tab"]')?.dataset.agenticFloatingPanelTabKey);
      if (index < 0) return;
      const next = { Home: 0, End: keys.length - 1, ArrowRight: (index + 1) % keys.length,
        ArrowLeft: (index + keys.length - 1) % keys.length }[event.key];
      if (typeof next !== 'number') return;
      event.preventDefault();
      select(keys[next], true);
    });
    header.append(rail, controls);
    inner.append(header, ...pages);
    dialog.append(inner);
    root.replaceChildren(dialog);
  }
  function open(key = activeKey ?? selected, { focus = true } = {}) {
    if (!keys.includes(key)) throw new RangeError('Unknown FloatingPanel tab');
    if (!tabs.size) build();
    const wasHidden = root.hidden;
    root.hidden = false;
    // A newly opened panel emits just the open transition, even when it targets a different tab.
    if (wasHidden) selected = key;
    select(key, focus);
    trigger.setAttribute('aria-expanded', 'true');
    if (wasHidden) onChange?.({ open: true, key });
  }
  function close(restoreFocus = true) {
    if (root.hidden) return;
    root.hidden = true;
    trigger.setAttribute('aria-expanded', 'false');
    onChange?.({ open: false, key: selected });
    if (restoreFocus) returnFocus();
  }
  function escape(event) {
    if (event.key !== 'Escape' || event.isComposing || event.defaultPrevented || root.hidden || event.composedPath().some(node => node.matches?.('dialog[open]'))) return;
    event.preventDefault();
    event.stopPropagation();
    close();
  }
  root.hidden = true;
  root.classList.add('agentic-base-floating-panel-root');
  root.dataset.agenticFloatingPanelPlacement = placement;
  trigger.setAttribute('aria-controls', root.id);
  trigger.setAttribute('aria-expanded', 'false');
  trigger.setAttribute('aria-haspopup', 'dialog');
  trigger.addEventListener('click', () => root.hidden ? open() : close());
  root.addEventListener('keydown', escape);
  trigger.addEventListener('keydown', escape);
  return { open, close, select, get activeKey() { return selected; }, get isOpen() { return !root.hidden; } };
}


/** Canonical section mechanics. Hosts own content, persistence and available geometry. */
export const PANEL_SECTION = Object.freeze({
  section: 'agentic-panel-section', header: 'agentic-panel-section-header',
  title: 'agentic-panel-section-title', actions: 'agentic-panel-section-actions',
  body: 'agentic-panel-section-body', scroll: 'agentic-panel-scroll-region',
  defaultCollapsed: true, expand: 'Expand section', collapse: 'Collapse section',
  expandAll: 'Expand All', collapseAll: 'Collapse All',
})

/** Restore focus before hiding content, without stealing focus from another section. */
export function recoverSectionFocus(body, trigger) {
  if (body?.contains(body.ownerDocument.activeElement)) trigger?.focus({ preventScroll: true })
}

export function isSectionGroupCollapsed(keys, collapsedKeys) {
  return keys.length > 0 && keys.every(key => collapsedKeys.has(key))
}
export function updateSectionGroup(previous, key, collapsed) {
  if (previous.has(key) === collapsed) return previous
  const next = new Set(previous)
  if (collapsed) next.add(key)
  else next.delete(key)
  return next
}

/** A native disclosure keeps the summary as the sole keyboard target and exposes a document heading. */
export function createPanelSectionSummary(doc, label, level = 3) {
  if (!Number.isInteger(level) || level < 1 || level > 6) throw new RangeError('Invalid section heading level')
  const summary = doc.createElement('summary')
  summary.className = PANEL_SECTION.header + ' agentic-panel-disclosure-summary'
  const heading = doc.createElement('h' + level)
  heading.className = PANEL_SECTION.title + ' agentic-panel-section-toggle'
  const text = doc.createElement('span')
  text.append(label)
  const chevron = createDesignIcon('ChevronDown', doc)
  chevron.classList.add('agentic-disclosure-chevron')
  heading.append(text, chevron)
  summary.append(heading)
  return summary
}

export function setPanelSectionExpanded(section, expanded) {
  if (section?.localName !== 'details' || typeof expanded !== 'boolean')
    throw new TypeError('A details section and boolean expansion state are required')
  const trigger = section.querySelector(':scope > summary')
  if (!trigger) throw new TypeError('A panel section requires a direct summary')
  if (!expanded && section.contains(section.ownerDocument.activeElement)
    && !trigger.contains(section.ownerDocument.activeElement)) trigger.focus({ preventScroll: true })
  if (section.open !== expanded) section.open = expanded
}

const installations = new WeakMap()
/** Enhance opted-in native details, retaining their nodes, events, values and native keys. */
export function installPanelSections(root = globalThis.document) {
  if (!root?.querySelectorAll || !root.addEventListener) throw new TypeError('A DOM root is required')
  if (installations.has(root)) return installations.get(root)
  const selector = 'details[data-agentic-section]'
  const prepare = section => {
    const summary = section.querySelector(':scope > summary')
    if (!summary) throw new TypeError('A panel section requires a direct summary')
    section.classList.add(PANEL_SECTION.section)
    summary.classList.add(PANEL_SECTION.header)
    summary.dataset.agenticSticky = section.dataset.agenticSticky === 'false' ? 'false' : 'true'
  }
  const refresh = () => {
    if (root.matches?.(selector)) prepare(root)
    root.querySelectorAll(selector).forEach(prepare)
  }
  const toggle = event => {
    const section = event.target
    if (!section.matches?.(selector) || section.open) return
    const summary = section.querySelector(':scope > summary')
    if (section.contains(section.ownerDocument.activeElement) && !summary.contains(section.ownerDocument.activeElement))
      summary.focus({ preventScroll: true })
  }
  const action = event => {
    const button = event.target.closest?.('[data-agentic-sections-action]')
    if (!button || !root.contains(button)) return
    const target = button.getAttribute('aria-controls')
    const group = target && (root.ownerDocument ?? root).getElementById(target)
    if (!group || !root.contains(group)) throw new TypeError('Section actions require a local aria-controls group')
    const sections = [...group.querySelectorAll(selector)]
    const command = button.dataset.agenticSectionsAction
    if (!['expand', 'collapse', 'toggle'].includes(command)) throw new TypeError('Unknown section action')
    const expanded = command === 'expand' || command === 'toggle' && sections.every(section => !section.open)
    sections.forEach(section => setPanelSectionExpanded(section, expanded))
  }
  refresh()
  root.addEventListener('toggle', toggle, true)
  root.addEventListener('click', action)
  const Observer = (root.ownerDocument ?? root).defaultView?.MutationObserver
  const observer = Observer && new Observer(refresh)
  observer?.observe(root, { childList: true, subtree: true })
  let active = true
  const dispose = () => {
    if (!active) return
    active = false
    observer?.disconnect()
    root.removeEventListener('toggle', toggle, true)
    root.removeEventListener('click', action)
    installations.delete(root)
  }
  installations.set(root, dispose)
  return dispose
}


export const collectionLayouts = Object.freeze([
  Object.freeze({ layout: 'list', label: 'List layout', icon: 'List' }),
  Object.freeze({ layout: 'card', label: 'Card layout', icon: 'Rows3' }),
  Object.freeze({ layout: 'grid', label: 'Grid layout', icon: 'LayoutGrid' }),
]);

/** Keep the host's layout state and callbacks independent of the shared controls. */
export function mountCollectionLayoutPicker(host, { layout, label, labelPrefix = '', onChange }) {
  const doc = host.ownerDocument;
  const controls = doc.createElement('div');
  controls.className = 'agentic-toggle-group';
  controls.setAttribute('role', 'group');
  controls.setAttribute('aria-label', label);
  const choices = new Map();
  for (const choice of collectionLayouts) {
    const button = doc.createElement('button');
    const name = labelPrefix ? `${labelPrefix} ${choice.label.toLowerCase()}` : choice.label;
    button.type = 'button';
    button.title = name;
    button.setAttribute('aria-label', name);
    button.dataset.agenticLayoutChoice = choice.layout;
    button.append(createDesignIcon(choice.icon, doc));
    button.addEventListener('click', () => onChange(choice.layout));
    controls.append(button);
    choices.set(choice.layout, button);
  }

  function setLayout(value) {
    if (!choices.has(value)) throw new RangeError('Unknown collection layout: ' + value);
    for (const [key, button] of choices) button.setAttribute('aria-pressed', String(key === value));
  }
  setLayout(layout);
  host.replaceChildren(controls);
  return { setLayout, destroy: () => controls.remove() };
}


export const skillsCommandsTab = Object.freeze({ key: 'skills-commands', label: 'Skills & Commands', icon: 'SquareTerminal' });
export const initialCatalogFilters = Object.freeze({ prefix: 'all', groupBy: 'subject', query: '', layout: 'list' });
const prefixes = [['slash', '/', 'Slash commands'], ['hash', '#', 'Hash semantics'], ['at', '@', 'At bindings']];
const facets = [['subject', 'S', 'Group by Subject'], ['verb', 'V', 'Group by Verb'], ['object', 'O', 'Group by Object']];

function element(doc, tag, className, text) {
  const node = doc.createElement(tag);
  if (className) node.className = className;
  if (text) node.textContent = text;
  return node;
}

/** The host supplies catalog data and disclosure state. The header never invokes entries. */
export function mountSkillsCommandsHeader(host, onChange) {
  const doc = host.ownerDocument;
  let filters = initialCatalogFilters, toggleGroups;
  const header = element(doc, 'header', 'agentic-skills-header');
  const heading = element(doc, 'h2', 'agentic-panel-section-title', skillsCommandsTab.label);
  const subtitle = element(doc, 'span', 'agentic-skills-meta', '/ # @ invocation catalog');
  const actions = element(doc, 'div', 'agentic-panel-section-actions');
  function button(label, face, click) {
    const control = element(doc, 'button', '', face);
    control.type = 'button';
    control.title = label;
    control.setAttribute('aria-label', label);
    control.addEventListener('click', click);
    return control;
  }
  const buttons = [];
  function change(field, value) {
    filters = { ...filters, [field]: value };
    if (field === 'layout') picker.setLayout(value);
    for (const { node, key, field } of buttons) {
      node.setAttribute('aria-pressed', String(filters[field] === key || filters[field] === 'all'));
    }
    onChange(filters);
  }
  function group(label, field, choices) {
    const container = element(doc, 'div', 'agentic-toggle-group');
    container.setAttribute('role', 'group');
    container.setAttribute('aria-label', label);
    for (const [key, face, name] of choices) {
      const node = button(name, face, () => change(field, field === 'prefix' && filters.prefix === key ? 'all' : key));
      node.setAttribute('aria-pressed', String(filters[field] === key || filters[field] === 'all'));
      buttons.push({ node, key, field });
      container.append(node);
    }
    return container;
  }
  const search = element(doc, 'input', 'agentic-form-control');
  search.type = 'search';
  search.placeholder = 'Search commands';
  search.setAttribute('aria-label', 'Search commands');
  search.hidden = true;
  function showSearch(open) {
    search.hidden = !open;
    searchToggle.setAttribute('aria-expanded', String(open));
    if (open) search.focus();
    else {
      if (search.value) { search.value = ''; change('query', ''); }
      searchToggle.focus();
    }
  }
  const searchToggle = button('Search skills and commands', '', () => showSearch(search.hidden));
  searchToggle.className = 'agentic-form-control';
  searchToggle.append(createDesignIcon('Search', doc));
  searchToggle.setAttribute('aria-expanded', 'false');
  search.addEventListener('input', () => change('query', search.value));
  search.addEventListener('keydown', event => {
    if (event.key !== 'Escape' || event.isComposing) return;
    event.preventDefault();
    event.stopPropagation();
    showSearch(false);
  });
  const disclosure = button(PANEL_SECTION.collapseAll, PANEL_SECTION.collapseAll, () => toggleGroups?.());
  disclosure.className = 'agentic-form-control';
  disclosure.hidden = true;
  const pickerHost = element(doc, 'div');
  const picker = mountCollectionLayoutPicker(pickerHost, {
    layout: filters.layout, label: 'Skills & Commands layout', onChange: value => change('layout', value),
  });
  actions.append(group('Skills & Commands prefix', 'prefix', prefixes), group('Skills & Commands group by', 'groupBy', facets), pickerHost, searchToggle, disclosure);
  header.append(heading, subtitle, actions, search);
  host.replaceChildren(header);
  return {
    setDisclosure(hasGroups, collapsed, toggle) {
      toggleGroups = toggle;
      disclosure.hidden = !hasGroups;
      const label = collapsed ? PANEL_SECTION.expandAll : PANEL_SECTION.collapseAll;
      disclosure.textContent = disclosure.title = label;
      disclosure.setAttribute('aria-label', label);
    },
    destroy() { picker.destroy(); header.remove(); },
  };
}

/** Render a browsable catalog. Interactive hosts can bind their own typed rows below the shared header. */
export function mountSkillsCommandsReference(host, entries, sourceLabel) {
  const doc = host.ownerDocument;
  host.dataset.panelTab = skillsCommandsTab.key;
  host.dataset.panelLabel = skillsCommandsTab.label;
  host.dataset.panelIcon = skillsCommandsTab.icon;
  const surface = element(doc, 'section', 'agentic-skills-catalog');
  const head = element(doc, 'div'), body = element(doc, 'div', 'agentic-skills-body');
  const source = element(doc, 'p', 'agentic-skills-meta', sourceLabel);
  const list = element(doc, 'div', 'agentic-collection agentic-skills-groups');
  body.append(source, list);
  surface.append(head, body);
  host.replaceChildren(surface);
  const closed = new Set();
  const header = mountSkillsCommandsHeader(head, render);
  function render({ prefix, groupBy, query, layout }) {
    const groups = new Map();
    const symbol = prefixes.find(([key]) => key === prefix)?.[1];
    const needle = query.trim().toLowerCase();
    for (const entry of entries) {
      if (symbol && !entry.token.startsWith(symbol)) continue;
      if (![entry.token, entry.summary, entry[groupBy]].join(' ').toLowerCase().includes(needle)) continue;
      const group = entry[groupBy];
      if (!groups.has(group)) groups.set(group, []);
      groups.get(group).push(entry);
    }
    const sections = [];
    function updateDisclosure() {
      const collapsed = sections.every(({ detail }) => !detail.open);
      header.setDisclosure(sections.length > 0, collapsed, () => {
        for (const { key, detail } of sections) {
          setPanelSectionExpanded(detail, collapsed);
          if (collapsed) closed.delete(key); else closed.add(key);
        }
        updateDisclosure();
      });
    }
    for (const [name, records] of groups) {
      const key = groupBy + ':' + name;
      const detail = element(doc, 'details', PANEL_SECTION.section + ' agentic-skills-group-section');
      detail.dataset.agenticSection = '';
      detail.open = !closed.has(key);
      const label = element(doc, 'span', 'agentic-skills-group-label', name + ' (' + records.length + ')');
      const summary = createPanelSectionSummary(doc, label);
      summary.dataset.agenticSticky = 'true';
      detail.append(summary);
      const rows = element(doc, 'div', 'agentic-collection');
      rows.dataset.layout = layout;
      for (const { token, summary } of records) {
        const row = element(doc, 'div', 'agentic-collection-item agentic-skills-row');
        row.dataset.layout = layout;
        const symbol = element(doc, 'span', layout === 'card' ? 'agentic-collection-preview' : 'agentic-collection-leading', token[0]);
        symbol.setAttribute('aria-hidden', 'true');
        const content = element(doc, 'div');
        content.append(element(doc, 'div', 'agentic-collection-title', token), element(doc, 'div', 'agentic-skills-meta', summary));
        row.append(symbol, content);
        rows.append(row);
      }
      detail.append(rows);
      detail.addEventListener('toggle', () => {
        if (!list.contains(detail)) return;
        if (detail.open) closed.delete(key); else closed.add(key);
        updateDisclosure();
      });
      sections.push({ key, detail });
    }
    list.replaceChildren(...sections.map(({ detail }) => detail));
    if (!sections.length) list.append(element(doc, 'p', '', 'No matching entries.'));
    updateDisclosure();
  }
  render(initialCatalogFilters);
  return { destroy() { header.destroy(); surface.remove(); } };
}

